import { Controller, Delete, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 삭제할 수 있는 상태는 반려·회수뿐이다.
const DELETABLE_STATUSES = ['반려', '회수'];
// 가정: 재기안 기반으로 쓸 수 있는 상태. 반려·회수 문서와 기작성 전자문서(결재가 끝난 승인·완료 문서)
const REDRAFT_STATUSES = ['반려', '회수', '승인', '완료'];
// 가정: 첨부파일의 소유 대상 유형 값
const ATTACHMENT_OWNER_TYPE = '결재문서';
// 가정: 변경 이력의 대상 유형 값
const HISTORY_TARGET_TYPE = 'approval_document';
// 가정: 문서번호 형식은 접두어-기간-순번이며 기간 단위가 바뀌어도 순번은 이어서 증가한다.

function parseId(value: string | undefined): string {
  if (value === undefined || !/^[0-9]{1,18}$/.test(value)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '결재문서 ID가 올바르지 않습니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr029107X9c9389Controller {
  @Delete('/approval-documents/:approvalDocumentId')
  async deleteApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const approvalDocumentId = parseId(req.params['approvalDocumentId']);
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT drafter_id AS "drafterId",
                approval_status AS "approvalStatus",
                document_number AS "documentNumber",
                title AS "title"
           FROM approval_document
          WHERE approval_document_id = CAST(:id AS bigint)`,
        { id: approvalDocumentId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '결재문서를 찾을 수 없습니다.');
      }
      const doc = rows[0];
      if (String(doc.drafterId) !== String(user.id)) {
        throw new ApiError(422, 'NOT_DRAFTER', '기안자만 문서를 삭제할 수 있습니다.');
      }
      if (!DELETABLE_STATUSES.includes(doc.approvalStatus)) {
        throw new ApiError(409, 'APPROVAL_DOCUMENT_STATUS_MISMATCH', '반려 또는 회수 상태의 문서만 삭제할 수 있습니다.');
      }
      const before = JSON.stringify({
        documentNumber: doc.documentNumber,
        title: doc.title,
        approvalStatus: doc.approvalStatus,
      });
      await db.execute(
        `DELETE FROM approval_line
          WHERE approval_document_id = CAST(:id AS bigint)`,
        { id: approvalDocumentId },
      );
      await db.execute(
        `DELETE FROM attachment
          WHERE owner_type = :ownerType
            AND owner_id = CAST(:id AS bigint)`,
        { ownerType: ATTACHMENT_OWNER_TYPE, id: approvalDocumentId },
      );
      await db.execute(
        `DELETE FROM approval_document
          WHERE approval_document_id = CAST(:id AS bigint)`,
        { id: approvalDocumentId },
      );
      await db.execute(
        `INSERT INTO change_history
           (target_type, target_id, change_type, changed_at, changer_id,
            before_content, after_content, created_at, updated_at)
         VALUES
           (:targetType, CAST(:id AS bigint), '삭제', now(), CAST(:userId AS bigint),
            :before, NULL, now(), now())`,
        {
          targetType: HISTORY_TARGET_TYPE,
          id: approvalDocumentId,
          userId: user.id,
          before,
        },
      );
      return {};
    });
  }

  @Post('/approval-documents/:approvalDocumentId/redraft')
  @HttpCode(200)
  async redraftApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const approvalDocumentId = parseId(req.params['approvalDocumentId']);
    const data = checks.inputOf(req.body);
    if (data['title'] !== undefined && data['title'] !== null) {
      if (typeof data['title'] !== 'string' || data['title'].trim() === '' || data['title'].length > 500) {
        throw new ApiError(400, 'VALIDATION_FAILED', '문서 제목은 500자 이내의 글자여야 합니다.');
      }
    }
    if (data['body'] !== undefined && data['body'] !== null && typeof data['body'] !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서 본문 형식이 올바르지 않습니다.');
    }
    for (const key of ['isUrgent', 'isSecret']) {
      const v = data[key];
      if (v !== undefined && v !== null && typeof v !== 'boolean') {
        throw new ApiError(400, 'VALIDATION_FAILED', '긴급결재·보안문서 여부는 true 또는 false여야 합니다.');
      }
    }
    return transaction(async (db) => {
      // 가정: 조회 권한은 기안자 또는 결재선에 있는 결재자로 본다. 권한이 없으면 없는 문서처럼 404.
      const sources = await db.query(
        `SELECT d.approval_form_id AS "approvalFormId",
                d.document_category_id AS "documentCategoryId",
                d.title AS "title",
                d.body AS "body",
                d.approval_status AS "approvalStatus",
                d.is_urgent AS "isUrgent",
                d.is_secret AS "isSecret"
           FROM approval_document d
          WHERE d.approval_document_id = CAST(:id AS bigint)
            AND (d.drafter_id = CAST(:userId AS bigint)
                 OR EXISTS (SELECT 1 FROM approval_line l
                             WHERE l.approval_document_id = d.approval_document_id
                               AND l.approver_id = CAST(:userId AS bigint)))`,
        { id: approvalDocumentId, userId: user.id },
      );
      if (sources.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '원본 문서를 찾을 수 없거나 조회 권한이 없습니다.');
      }
      const source = sources[0];
      if (!REDRAFT_STATUSES.includes(source.approvalStatus)) {
        throw new ApiError(409, 'APPROVAL_DOCUMENT_STATUS_MISMATCH', '재기안할 수 없는 상태의 문서입니다.');
      }
      const employees = await db.query(
        `SELECT department_id AS "departmentId"
           FROM employee
          WHERE employee_id = CAST(:userId AS bigint)`,
        { userId: user.id },
      );
      if (employees.length === 0 || employees[0].departmentId === null) {
        throw new ApiError(400, 'VALIDATION_FAILED', '기안자의 소속 부서가 없어 재기안할 수 없습니다.');
      }
      const departmentId = employees[0].departmentId;
      const rules = await db.query(
        `SELECT numbering_rule_id AS "numberingRuleId"
           FROM numbering_rule
          WHERE target_type = 'DOCUMENT'
            AND (department_id = CAST(:departmentId AS bigint) OR department_id IS NULL)
          ORDER BY department_id NULLS LAST, numbering_rule_id
          LIMIT 1
            FOR UPDATE`,
        { departmentId },
      );
      if (rules.length === 0) {
        throw new ApiError(409, 'INVALID_STATE', '문서번호 채번 규칙이 없습니다.');
      }
      const numbered = await db.query(
        `UPDATE numbering_rule
            SET current_sequence = COALESCE(current_sequence, 0) + 1,
                updated_at = now()
          WHERE numbering_rule_id = CAST(:ruleId AS bigint)
        RETURNING prefix AS "prefix",
                  digits AS "digits",
                  current_sequence AS "currentSequence",
                  to_char(now(), CASE reset_unit
                                   WHEN 'DAY' THEN 'YYYYMMDD'
                                   WHEN 'MONTH' THEN 'YYYYMM'
                                   ELSE 'YYYY' END) AS "period"`,
        { ruleId: rules[0].numberingRuleId },
      );
      const n = numbered[0];
      const seq = String(n.currentSequence).padStart(Number(n.digits), '0');
      const documentNumber = [n.prefix, n.period, seq].filter((p) => p !== null && p !== '').join('-');
      const title = typeof data['title'] === 'string' ? data['title'] : source.title;
      const body = typeof data['body'] === 'string' ? data['body'] : source.body;
      const isUrgent = typeof data['isUrgent'] === 'boolean' ? data['isUrgent'] : source.isUrgent;
      const isSecret = typeof data['isSecret'] === 'boolean' ? data['isSecret'] : source.isSecret;
      const created = await db.query(
        `INSERT INTO approval_document
           (approval_form_id, drafter_id, drafter_department_id, document_category_id,
            document_number, title, body, approval_status, is_urgent, is_secret,
            created_at, updated_at)
         VALUES
           (CAST(:formId AS bigint), CAST(:userId AS bigint), CAST(:departmentId AS bigint),
            CAST(:categoryId AS bigint), :documentNumber, :title, :body, '기안',
            :isUrgent, :isSecret, now(), now())
         RETURNING approval_document_id AS "approvalDocumentId",
                   document_number AS "documentNumber",
                   approval_status AS "approvalStatus"`,
        {
          formId: source.approvalFormId,
          userId: user.id,
          departmentId,
          categoryId: source.documentCategoryId,
          documentNumber,
          title,
          body,
          isUrgent,
          isSecret,
        },
      );
      const row = created[0];
      const after = JSON.stringify({
        sourceApprovalDocumentId: approvalDocumentId,
        documentNumber: row.documentNumber,
        title,
        approvalStatus: row.approvalStatus,
      });
      await db.execute(
        `INSERT INTO change_history
           (target_type, target_id, change_type, changed_at, changer_id,
            before_content, after_content, created_at, updated_at)
         VALUES
           (:targetType, CAST(:newId AS bigint), '등록', now(), CAST(:userId AS bigint),
            NULL, :after, now(), now())`,
        {
          targetType: HISTORY_TARGET_TYPE,
          newId: row.approvalDocumentId,
          userId: user.id,
          after,
        },
      );
      return row;
    });
  }
}

