import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Select,
  Pairs,
  Tiles,
  TextInput,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr029107X9c9389Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [mode, setMode] = useState<'' | 'delete' | 'redraft'>('');
  const [detail, setDetail] = useState<Row | null>(null);
  const [targetId, setTargetId] = useState<number | string>('');
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [isUrgent, setIsUrgent] = useState('');
  const [isSecret, setIsSecret] = useState('');

  const boolOptions: [string, string][] = [
    ['true', '예'],
    ['false', '아니오'],
  ];

  function openDrawer(next: 'delete' | 'redraft') {
    setTargetId('');
    setTitle('');
    setBody('');
    setIsUrgent('');
    setIsSecret('');
    setMode(next);
  }

  function addResult(row: Row) {
    setResults((prev) => [row, ...prev]);
  }

  async function submitDelete() {
    if (targetId === '') {
      throw new Error('삭제할 문서를 선택하세요.');
    }
    await call('DELETE', '/approval-documents/' + targetId, role);
    addResult({ kind: '삭제', documentNumber: '', approvalStatus: '삭제', at: new Date().toISOString() });
    notify('문서를 삭제했습니다.');
    setMode('');
  }

  async function submitRedraft() {
    if (targetId === '') {
      throw new Error('재기안할 원본 문서를 선택하세요.');
    }
    const payload: Row = {};
    if (title.trim() !== '') payload['title'] = title;
    if (body.trim() !== '') payload['body'] = body;
    if (isUrgent !== '') payload['isUrgent'] = isUrgent === 'true';
    if (isSecret !== '') payload['isSecret'] = isSecret === 'true';
    const created = await call('POST', '/approval-documents/' + targetId + '/redraft', role, payload);
    addResult({
      kind: '재기안',
      approvalDocumentId: created['approvalDocumentId'],
      documentNumber: created['documentNumber'],
      approvalStatus: created['approvalStatus'],
      at: new Date().toISOString(),
    });
    notify('재기안 문서를 만들었습니다.');
    setMode('');
  }

  const redraftCount = results.filter((r) => r['kind'] === '재기안').length;
  const deleteCount = results.filter((r) => r['kind'] === '삭제').length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['재기안', redraftCount],
            ['삭제', deleteCount],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>처리 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={() => openDrawer('redraft')}>재기안</button>
          <button type="button" onClick={() => openDrawer('delete')}>삭제</button>
        </Band>
        <DataTable
          rows={results}
          empty="이 화면에서 처리한 문서가 없습니다."
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'kind', label: '구분' },
            { key: 'documentNumber', label: '문서번호' },
            { key: 'approvalStatus', label: '결재 진행 상태', render: (row) => <Badge value={row['approvalStatus']} /> },
            { key: 'at', label: '처리 일시', render: (row) => <DateText value={row['at']} time /> },
          ]}
        />
      </section>
      {mode === 'delete' && (
        <Drawer title="반려·회수 문서 삭제" onClose={() => setMode('')}>
          <Form
            onSubmit={submitDelete}
            submit="삭제"
            danger
            note="반려 또는 회수 상태의 내 문서만 삭제할 수 있으며 삭제한 문서는 복구되지 않습니다."
          >
            <Field label="결재문서" required wide>
              <LookupSelect table="approval_document" role={role} value={targetId} onChange={setTargetId} />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'redraft' && (
        <Drawer title="재기안" onClose={() => setMode('')}>
          <Form onSubmit={submitRedraft} submit="재기안" note="비워 두면 원본 문서의 내용을 그대로 복사합니다. 새 문서번호가 부여됩니다.">
            <Field label="원본 결재문서" required wide>
              <LookupSelect table="approval_document" role={role} value={targetId} onChange={setTargetId} />
            </Field>
            <Field label="문서 제목" wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="문서 본문" wide>
              <TextInput value={body} onChange={setBody} multiline />
            </Field>
            <Field label="긴급결재 여부">
              <Select value={isUrgent} onChange={setIsUrgent} options={boolOptions} placeholder="원본 유지" />
            </Field>
            <Field label="보안문서 여부">
              <Select value={isSecret} onChange={setIsSecret} options={boolOptions} placeholder="원본 유지" />
            </Field>
          </Form>
        </Drawer>
      )}
      {detail && (
        <Drawer title="처리 내역" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['구분', String(detail['kind'])],
              ['문서번호', String(detail['documentNumber'] ?? '')],
              ['결재 진행 상태', <Badge value={detail['approvalStatus']} />],
              ['처리 일시', <DateText value={detail['at']} time />],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
